bool valid_parentheses(const char *s) {
    int n = (int)strlen(s);
    char *st = malloc((size_t)(n > 0 ? n : 1));
    int top = 0;
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) { free(st); return false; }
            char o = st[--top];
            if ((c == ')' && o != '(') ||
                (c == ']' && o != '[') ||
                (c == '}' && o != '{')) { free(st); return false; }
        }
    }
    bool ok = (top == 0);
    free(st);
    return ok;
}

#define MINSTACK_CAP 128
typedef struct { int val[MINSTACK_CAP]; int mn[MINSTACK_CAP]; int top; } MinStack;

void ms_init(MinStack *m)         { m->top = 0; }
void ms_push(MinStack *m, int x)  {
    m->val[m->top] = x;
    m->mn[m->top]  = (m->top == 0) ? x : (x < m->mn[m->top-1] ? x : m->mn[m->top-1]);
    m->top++;
}
void ms_pop(MinStack *m)          { if (m->top > 0) m->top--; }
int  ms_top(const MinStack *m)    { return m->val[m->top-1]; }
int  ms_getmin(const MinStack *m) { return m->mn[m->top-1]; }

void next_greater_element(const int *a, int n, int *out) {
    for (int i = 0; i < n; ++i) out[i] = -1;
    istk_t st; istk_init(&st, n);              // index monotonic-decreasing stack
    for (int i = 0; i < n; ++i) {
        while (!istk_empty(&st) && a[istk_peek(&st)] < a[i])
            out[istk_pop(&st)] = a[i];         // current value answers the waiters
        istk_push(&st, i);
    }
    istk_free(&st);
}

void daily_temperatures(const int *t, int n, int *out) {
    for (int i = 0; i < n; ++i) out[i] = 0;
    istk_t st; istk_init(&st, n);
    for (int i = 0; i < n; ++i) {
        while (!istk_empty(&st) && t[istk_peek(&st)] < t[i]) {
            int j = istk_pop(&st);
            out[j] = i - j;                    // day gap is the answer
        }
        istk_push(&st, i);
    }
    istk_free(&st);
}

int eval_rpn(const char **tok, int n) {
    istk_t st; istk_init(&st, n > 0 ? n : 1);
    for (int i = 0; i < n; ++i) {
        const char *t = tok[i];
        if (t[1] == '\0' && (t[0]=='+'||t[0]=='-'||t[0]=='*'||t[0]=='/')) {
            int b = istk_pop(&st);             // pop b first!
            int a = istk_pop(&st);
            int r = 0;
            switch (t[0]) {
                case '+': r = a + b; break;
                case '-': r = a - b; break;
                case '*': r = a * b; break;
                case '/': r = a / b; break;
            }
            istk_push(&st, r);
        } else {
            istk_push(&st, atoi(t));           // negatives like "-11"
        }
    }
    int res = istk_empty(&st) ? 0 : istk_pop(&st);
    istk_free(&st);
    return res;
}

typedef struct { istk_t in; istk_t out; } Queue2;

void q2_init(Queue2 *q, int cap) { istk_init(&q->in, cap); istk_init(&q->out, cap); }
void q2_free(Queue2 *q)          { istk_free(&q->in); istk_free(&q->out); }
void q2_enqueue(Queue2 *q, int x){ istk_push(&q->in, x); }
static void q2_shift(Queue2 *q)  {                 // flip only when out is empty
    if (istk_empty(&q->out))
        while (!istk_empty(&q->in)) istk_push(&q->out, istk_pop(&q->in));
}
int  q2_dequeue(Queue2 *q)       { q2_shift(q); return istk_pop(&q->out); }
int  q2_peek(Queue2 *q)          { q2_shift(q); return istk_peek(&q->out); }
bool q2_empty(const Queue2 *q)   { return istk_empty(&q->in) && istk_empty(&q->out); }

void sliding_window_max(const int *a, int n, int k, int *out) {
    if (n == 0 || k <= 0) return;
    int *dq = malloc(sizeof(int) * (size_t)n);     // deque of indices, [head, tail)
    int head = 0, tail = 0, oi = 0;
    for (int i = 0; i < n; ++i) {
        if (head < tail && dq[head] <= i - k) head++;            // drop expired front
        while (head < tail && a[dq[tail-1]] <= a[i]) tail--;     // drop smaller back
        dq[tail++] = i;
        if (i >= k - 1) out[oi++] = a[dq[head]];                 // window max = front
    }
    free(dq);
}

typedef struct { char *buf; int len; int cap; } sb_t;
static void sb_init(sb_t *b)         { b->cap=16; b->len=0; b->buf=malloc(16); b->buf[0]='\0'; }
static void sb_putc(sb_t *b, char c) { if (b->len+1>=b->cap){ b->cap*=2; b->buf=realloc(b->buf,(size_t)b->cap);} b->buf[b->len++]=c; b->buf[b->len]='\0'; }
static void sb_puts(sb_t *b, const char *s) { while (*s) sb_putc(b, *s++); }

char *decode_string(const char *s) {
    int n = (int)strlen(s);
    istk_t nums; istk_init(&nums, n + 1);              // repeat-count stack
    sb_t *strs = malloc(sizeof(sb_t) * (size_t)(n+1)); // outer-string stack
    int sp = 0;
    sb_t cur; sb_init(&cur);
    int num = 0;
    for (const char *p = s; *p; ++p) {
        char c = *p;
        if (isdigit((unsigned char)c)) {
            num = num * 10 + (c - '0');                // multi-digit
        } else if (c == '[') {
            istk_push(&nums, num); num = 0;
            strs[sp++] = cur; sb_init(&cur);           // save state, start inner
        } else if (c == ']') {
            int k = istk_pop(&nums);
            sb_t prev = strs[--sp];
            for (int i = 0; i < k; ++i) sb_puts(&prev, cur.buf);  // repeat k times
            free(cur.buf);
            cur = prev;
        } else {
            sb_putc(&cur, c);
        }
    }
    istk_free(&nums); free(strs);
    return cur.buf;   // caller frees
}
